package com.medicine.reminder.controller; import com.medicine.reminder.model.*; import com.medicine.reminder.repository.ProfileRepository; import com.medicine.reminder.service.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController public class HistoryController {private final HistoryService history;private final ProfileRepository profiles;public HistoryController(HistoryService h,ProfileRepository p){history=h;profiles=p;}private Long u(Authentication a){return(Long)a.getDetails();}
 @GetMapping("/api/history") public List<Map<String,Object>> list(@RequestParam Long profileId,Authentication a){if(profiles.findByIdAndUserId(profileId,u(a)).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found");return history.list(profileId).stream().map(this::view).toList();}
 @PostMapping("/api/history") public Map<String,Object> log(@RequestBody Map<String,String>d,Authentication a){try{return view(history.log(Long.valueOf(d.get("reminderId")),d.get("status"),u(a)));}catch(NumberFormatException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid reminder");}}
 private Map<String,Object> view(MedicineHistory h){Reminder r=h.getReminder();Medicine m=r.getMedicine();return Map.of("id",h.getId(),"takenAt",h.getTakenAt(),"status",h.getStatus(),"scheduledTime",r.getTime(),"medicine",m.getName(),"profile",m.getProfile().getName(),"reminderId",r.getId());}}
